/**
 * Config Plugin: withReleaseSigning
 *
 * `android/` is generated by `expo prebuild` and must never be hand-edited, so
 * the release signing config is injected here instead.
 *
 * It appends a guarded `android { }` block to android/app/build.gradle. When the
 * KIOSK_* env vars are present, the release buildType is signed with a real
 * keystore; when they are absent (normal local/dev builds) the block is inert
 * and Gradle keeps the generated default (the debug key).
 *
 * Env vars consumed at build time:
 *   KIOSK_KEYSTORE_FILE      absolute path to the .jks/.keystore file
 *   KIOSK_KEYSTORE_PASSWORD  keystore password
 *   KIOSK_KEY_ALIAS          key alias
 *   KIOSK_KEY_PASSWORD       key password
 *
 * Generate a keystore and build locally — see docs/PRODUCTION.md §5–§7. In CI
 * the keystore is written from a base64 secret and these vars are exported.
 */
import { ConfigPlugin, withAppBuildGradle } from "@expo/config-plugins";

const MARKER = "// @generated by plugins/withReleaseSigning.ts";

const SIGNING_BLOCK = `
${MARKER}
def kioskStoreFile = System.getenv("KIOSK_KEYSTORE_FILE")
if (kioskStoreFile != null && !kioskStoreFile.isEmpty()) {
    android {
        signingConfigs {
            release {
                storeFile file(kioskStoreFile)
                storePassword System.getenv("KIOSK_KEYSTORE_PASSWORD")
                keyAlias System.getenv("KIOSK_KEY_ALIAS")
                keyPassword System.getenv("KIOSK_KEY_PASSWORD")
            }
        }
        buildTypes {
            release {
                signingConfig signingConfigs.release
            }
        }
    }
    println "[withReleaseSigning] release build will be signed with ${"$"}{kioskStoreFile}"
} else {
    println "[withReleaseSigning] KIOSK_KEYSTORE_FILE not set - release build will use the generated debug key"
}
`;

const withReleaseSigning: ConfigPlugin = (config) => {
  return withAppBuildGradle(config, (gradleConfig) => {
    if (gradleConfig.modResults.language !== "groovy") {
      throw new Error(
        "withReleaseSigning: expected android/app/build.gradle to be Groovy",
      );
    }

    // prebuild --clean regenerates the file, but guard against double-injection
    // when prebuild runs without --clean.
    if (!gradleConfig.modResults.contents.includes(MARKER)) {
      gradleConfig.modResults.contents += SIGNING_BLOCK;
    }

    return gradleConfig;
  });
};

export default withReleaseSigning;
